const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry for Pakistan (bounding box)
  const pakistan = ee.Geometry.Rectangle([61.0, 23.5, 75.5, 37.0]);

  // 2. Time periods
  const jan2018 = ['2018-01-01', '2018-02-01'];
  const aug2018 = ['2018-08-01', '2018-09-01'];

  // 3. Data acquisition - MODIS ET product
  const getET = (dateRange) => {
    return ee.ImageCollection('MODIS/006/MOD16A2')
      .filterDate(dateRange[0], dateRange[1])
      .select('ET')  // kg/m²/8-day
      .map(img => img.multiply(0.1));  // Convert to mm/8-day
  };

  const janCol = getET(jan2018);
  const augCol = getET(aug2018);

  // 4. Check data availability
  const janCount = janCol.size().getInfo();
  const augCount = augCol.size().getInfo();

  console.log(`January 2018 Images: ${janCount}`);
  console.log(`August 2018 Images: ${augCount}`);

  if (janCount === 0 || augCount === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Calculate monthly ET (sum of 8-day composites)
  const janET = janCol.sum();
  const augET = augCol.sum();

  // 6. Reduce to region with pixel count check
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const janResult = janET.reduceRegion({
    reducer: reducer,
    geometry: pakistan,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const augResult = augET.reduceRegion({
    reducer: reducer,
    geometry: pakistan,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const janAvg = janResult.ET_mean;
  const janPixels = janResult.ET_count;
  const augAvg = augResult.ET_mean;
  const augPixels = augResult.ET_count;

  console.log(`January ET: ${janAvg?.toFixed(2)} mm (Pixels: ${janPixels})`);
  console.log(`August ET: ${augAvg?.toFixed(2)} mm (Pixels: ${augPixels})`);

  // 7. Validate results
  if (janPixels === 0 || augPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (janAvg === null || augAvg === null || 
      isNaN(janAvg) || isNaN(augAvg) ||
      janAvg < 0 || augAvg < 0 || janAvg > 1000 || augAvg > 1000) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 8. Compare ET values
  const etIncrease = augAvg > janAvg;
  console.log(`ET Change: ${((augAvg - janAvg) / janAvg * 100).toFixed(1)}%`);

  // 9. Output final answer
  if (etIncrease) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
